local TypesettingMachineMaker = {}
local PRODUCTS = {
    simple_wood_typesetting = { name = "Preprost leseni tipografski stroj", woodCost = 4, ironCost = 2, leadCost = 1, time = 6, cost = 250, science = 28, happiness = 2, description = "Preprost leseni tipografski stroj za stavljenje besedila." },
    iron_reinforced_typesetting = { name = "Železnookrepljen tipografski stroj", woodCost = 4, ironCost = 3, leadCost = 1, time = 9, cost = 580, science = 42, happiness = 2, prestige = 2, description = "Železnookrepljen tipografski stroj za trgovce." },
    silver_geared_typesetting = { name = "Srebrnozobčan tipografski stroj", woodCost = 4, silverCost = 1, ironCost = 3, leadCost = 1, time = 13, cost = 1300, science = 58, happiness = 3, prestige = 6, description = "Srebrnozobčan tipografski stroj za plemiče." },
    gold_trimmed_typesetting = { name = "Zlatookrasni tipografski stroj", woodCost = 4, goldCost = 1, silverCost = 1, ironCost = 3, leadCost = 1, time = 17, cost = 3000, science = 72, happiness = 4, prestige = 14, description = "Zlatookrasni tipografski stroj za visoke plemiče." },
    jewel_set_typesetting = { name = "Draguljasta tipografski stroj", woodCost = 4, goldCost = 1, silverCost = 1, ironCost = 3, leadCost = 1, jewelCost = 1, time = 21, cost = 6400, science = 85, happiness = 6, prestige = 27, description = "Tipografski stroj z draguljem za visoko plemstvo." },
    royal_grand_typesetting = { name = "Kraljevski veliki tipografski stroj", woodCost = 6, goldCost = 2, silverCost = 2, ironCost = 3, leadCost = 1, jewelCost = 2, pearlCost = 2, time = 28, cost = 14000, science = 95, happiness = 12, prestige = 58, description = "Veliki kraljevski tipografski stroj z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    typesetting_workshop = { name = "Tipografska delavnica", cost = { gold = 310, wood = 160, stone = 140, iron = 6, lead = 4 }, upkeep = 7, qualityBonus = 5 },
    printing_loft = { name = "Tiskarska podstrešje", cost = { gold = 1100, wood = 320, stone = 280, silver = 6, iron = 8 }, upkeep = 26, qualityBonus = 18 },
    master_typesetting_atelier = { name = "Mojstrski tipografski atelje", cost = { gold = 2900, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 68, qualityBonus = 30 },
    royal_printing_palace = { name = "Kraljevska tiskarska palača", cost = { gold = 12500, wood = 600, stone = 800, gold = 78, jewel = 18 }, upkeep = 250, qualityBonus = 55, prestigeBonus = 50 },
}
TypesettingMachineMaker.woodStock = 20; TypesettingMachineMaker.ironStock = 14; TypesettingMachineMaker.leadStock = 8; TypesettingMachineMaker.silverStock = 6; TypesettingMachineMaker.goldStock = 6; TypesettingMachineMaker.jewelStock = 4; TypesettingMachineMaker.pearlStock = 4
TypesettingMachineMaker.productStock = {}; TypesettingMachineMaker.buildings = {}; TypesettingMachineMaker.maker = nil; TypesettingMachineMaker.activeMaking = {}; TypesettingMachineMaker.totalProducts = 0; TypesettingMachineMaker.dayTimer = 0
function TypesettingMachineMaker.init() TypesettingMachineMaker.woodStock=20; TypesettingMachineMaker.ironStock=14; TypesettingMachineMaker.leadStock=8; TypesettingMachineMaker.silverStock=6; TypesettingMachineMaker.goldStock=6; TypesettingMachineMaker.jewelStock=4; TypesettingMachineMaker.pearlStock=4; TypesettingMachineMaker.productStock={}; TypesettingMachineMaker.buildings={}; TypesettingMachineMaker.maker=nil; TypesettingMachineMaker.activeMaking={}; TypesettingMachineMaker.totalProducts=0; TypesettingMachineMaker.dayTimer=0; print("[TypesettingMachineMaker] Royal Typesetting Machine Maker System initialized (6 products, 4 buildings)") end
function TypesettingMachineMaker.hireMaker(n,s) s=s or math.random(55,90); local c=600+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; TypesettingMachineMaker.maker={name=n or ("Tipograf "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tipograf najet: %s (spretnost: %d)",TypesettingMachineMaker.maker.name,s),"success") end; return true end
function TypesettingMachineMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function TypesettingMachineMaker.build(id) local ok,e=TypesettingMachineMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(TypesettingMachineMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function TypesettingMachineMaker.getQualityBonus() local b=0; for _,bd in ipairs(TypesettingMachineMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function TypesettingMachineMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and TypesettingMachineMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and TypesettingMachineMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.leadCost and TypesettingMachineMaker.leadStock<(d.leadCost or 0) then return false,"Premalo svinca" end; if d.silverCost and TypesettingMachineMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and TypesettingMachineMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and TypesettingMachineMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and TypesettingMachineMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #TypesettingMachineMaker.buildings==0 then return false,"Potrebna tipografska delavnica" end; if not TypesettingMachineMaker.maker then return false,"Potreben tipograf" end; return true end
function TypesettingMachineMaker.make(pt,qty) qty=qty or 1; local ok,e=TypesettingMachineMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then TypesettingMachineMaker.woodStock=TypesettingMachineMaker.woodStock-d.woodCost*qty end; if d.ironCost then TypesettingMachineMaker.ironStock=TypesettingMachineMaker.ironStock-d.ironCost*qty end; if d.leadCost then TypesettingMachineMaker.leadStock=TypesettingMachineMaker.leadStock-d.leadCost*qty end; if d.silverCost then TypesettingMachineMaker.silverStock=TypesettingMachineMaker.silverStock-d.silverCost*qty end; if d.goldCost then TypesettingMachineMaker.goldStock=TypesettingMachineMaker.goldStock-d.goldCost*qty end; if d.jewelCost then TypesettingMachineMaker.jewelStock=TypesettingMachineMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then TypesettingMachineMaker.pearlStock=TypesettingMachineMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if TypesettingMachineMaker.maker then t=math.max(1,t-math.floor(TypesettingMachineMaker.maker.skill/13)) end; table.insert(TypesettingMachineMaker.activeMaking,{id="typesettingmachine_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Gradnja: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function TypesettingMachineMaker.completeMaking(m) local q=1.0+(TypesettingMachineMaker.getQualityBonus()/100); if TypesettingMachineMaker.maker then q=q+(TypesettingMachineMaker.maker.skill/140) end; q=math.min(2.5,q); TypesettingMachineMaker.productStock[m.productType]=(TypesettingMachineMaker.productStock[m.productType] or 0)+m.quantity; TypesettingMachineMaker.totalProducts=TypesettingMachineMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if TypesettingMachineMaker.maker then TypesettingMachineMaker.maker.itemsMade=TypesettingMachineMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then TypesettingMachineMaker.maker.skill=math.min(100,TypesettingMachineMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tipografski stroj izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"typesettingmachine.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function TypesettingMachineMaker.update(dt) if not _G.state then return end; TypesettingMachineMaker.dayTimer=TypesettingMachineMaker.dayTimer+dt; if TypesettingMachineMaker.dayTimer>=30 then TypesettingMachineMaker.dayTimer=0; for i=#TypesettingMachineMaker.activeMaking,1,-1 do local m=TypesettingMachineMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then TypesettingMachineMaker.completeMaking(m); table.remove(TypesettingMachineMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(TypesettingMachineMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if TypesettingMachineMaker.maker then tu=tu+16 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function TypesettingMachineMaker.getStats() return {woodStock=TypesettingMachineMaker.woodStock,ironStock=TypesettingMachineMaker.ironStock,leadStock=TypesettingMachineMaker.leadStock,silverStock=TypesettingMachineMaker.silverStock,goldStock=TypesettingMachineMaker.goldStock,jewelStock=TypesettingMachineMaker.jewelStock,pearlStock=TypesettingMachineMaker.pearlStock,productStock=TypesettingMachineMaker.productStock,numBuildings=#TypesettingMachineMaker.buildings,hasMaker=TypesettingMachineMaker.maker~=nil,makerName=TypesettingMachineMaker.maker and TypesettingMachineMaker.maker.name or "—",makerSkill=TypesettingMachineMaker.maker and TypesettingMachineMaker.maker.skill or 0,activeMaking=#TypesettingMachineMaker.activeMaking,totalProducts=TypesettingMachineMaker.totalProducts} end
return TypesettingMachineMaker
